      "Handling time": "Menetlusaeg",
      "Handling time (minutes)": "Menetlusaeg (minutites)",
      "Handling time runs from submission to the final decision, including nights, weekends and time waiting. It is attributed to the final decision-maker; it does not measure active working time. Averages count each application once and exclude missing or invalid timestamps. Document totals count each selected type once per application, including archived records, not originals or copies. Times are shown in UK time.": "Menetlusaeg kulgeb esitamisest lõppotsuseni, hõlmates öid, nädalavahetusi ja ooteaega. See omistatakse lõppotsustajale ega mõõda aktiivset tööaega. Keskmistes loetakse iga taotlus üks kord ning vigased või puuduvad ajatemplid jäetakse välja. Dokumendiarvud loevad iga valitud tüübi kord taotluse kohta, sh arhiveeritud kirjed, mitte originaale ega koopiaid. Ajad on ÜK ajas.",
