      "How will evidence be supplied?": "Kuidas esitatakse tõendid?",
      "How your chamber will receive the commercial invoice and any other documents.": "Kuidas koda saab kaubaarve ja muud dokumendid.",
      "IIC issuing arrangements are limited and requirements depend on the requesting overseas authority. Confirm acceptance and the issuing route before completing the form.": "IIC väljastamise võimalused on piiratud ja nõuded sõltuvad taotlevast välisriigi asutusest. Enne vormi täitmist kinnitage aktsepteerimine ja väljastamisviis.",
      "ISSUED RETROSPECTIVELY": "VÄLJASTATUD TAGANTJÄRELE",
      "Identify both parties to the preferential trade arrangement, using the applicable country or territory wording.": "Märkige mõlemad sooduskaubanduse pooled asjakohaste riigi- või territooriuminimetustega.",
      "Identify each article with make, model and serial number where relevant. State NSN where appropriate; packaging alone is insufficient.": "Määratlege iga ese vajadusel margi, mudeli ja seerianumbriga. Sobivusel märkige NSN; ainult pakendist ei piisa.",
      "Identify each product and its correct commodity code. Include the origin information required by the market.": "Määratlege iga toode ja selle õige kaubakood. Lisage turu nõutud päritoluinfo.",
      "Identify the destination partner. Check the applicable agreement and any special territorial wording.": "Määratlege sihtpartner. Kontrollige kohaldatavat kokkulepet ja eriterritooriumide sõnastust.",
      "Identify the method of transport.": "Märkige transpordiviis.",
      "Identify the originating organisation and final destination; add UK representative details where required.": "Märkige lähteorganisatsioon ja lõppsihtkoht; vajaduse korral lisage ÜK esindaja.",
