      "Identify the responsible company or individual; the holder bears liability if the Carnet is misused.": "Märkige vastutav ettevõte või isik; märkmiku väärkasutuse eest vastutab valdaja.",
      "If different from the importer, give the intended user’s name and address.": "Kui kasutaja erineb importijast, esitage tema nimi ja aadress.",
