      "In Trade Documents, enter marks, package details and goods descriptions in the separate goods fields. They are composed into this single printed box. Check the live preview and resolve any fit warning.": "Sisestage Trade Documentsis märgistus, pakendiandmed ja kaubakirjeldused eraldi väljadele. Need ühendatakse ühte prindilahtrisse. Kontrollige reaalaja eelvaadet ja lahendage mahutavuse hoiatused.",
