      "On the application copy, identify an applicant different from the consignor.": "Märkige taotluse eksemplarile kaubasaatjast erinev taotleja.",
      "On the application copy, provide place, date and authorised signatory. Keep certification areas for the chamber.": "Lisage taotluse eksemplarile koht, kuupäev ja volitatud allkirjastaja. Jätke kinnitusalad kojale.",
