      "Only these signature strokes will be saved. Check for missing strokes or extra text.": "Salvestatakse ainult need allkirjajooned. Kontrollige puuduvaid jooni ja üleliigset teksti.",
      "Open Applications, choose Pending, and select Review. Check the documents, assign a certificate number and signatory, then approve or reject.": "Avage Taotlused, valige Ootel ja Vaata üle. Kontrollige dokumente, määrake sertifikaadi number ja allkirjastaja ning kiitke heaks või lükake tagasi.",
      "Open Exporters, manage the account, then choose Payments & pricing. Assign an active pricing list and save.": "Avage Eksportijad, hallake kontot ja valige Maksed ja hinnad. Määrake aktiivne hinnakiri ning salvestage.",
      "Open My account → Users & access → Add user. Choose a role and save. This prototype records a sample invitation without sending email.": "Avage Minu konto → Kasutajad ja juurdepääs → Lisa kasutaja. Valige roll ning salvestage. Prototüüp salvestab näidiskutse ilma e-kirja saatmata.",
      "Open Settings → Signatories. Add a name and job title, and optionally a sample image. Rotate, adjust contrast and crop its edges before saving.": "Avage Seaded → Allkirjastajad. Lisage nimi, ametinimetus ja soovi korral näidispilt. Enne salvestamist pöörake, reguleerige kontrasti ning kärpige servi.",
      "Open an application and choose Copy. It creates an independent draft with a new reference. Review the details before submitting.": "Avage taotlus ja valige Kopeeri. Luuakse sõltumatu mustand uue viitega. Vaadake andmed enne esitamist üle.",
