      "The file could not be read. Try copying the cells into the box instead.": "Faili ei saanud lugeda. Proovige lahtrid selle asemel kasti kopeerida.",
      "The goods are of foreign origin as proved by the documents attached to this application as per Standard Rules (e.g. foreign certificate of origin, certified invoice, customs declaration or other documents).": "Kaup on välismaist päritolu, mida tõendavad standardreeglite kohased taotlusele lisatud dokumendid (nt välismaine päritolusertifikaat, kinnitatud arve, tollideklaratsioon või muud dokumendid).",
      "The goods whilst not comprised wholly of United Kingdom components or materials, are entitled to be considered as of United Kingdom origin by virtue of the economically justified substantial process which has occurred in the United Kingdom, as indicated below.": "Kuigi kaup ei koosne täielikult Ühendkuningriigi osadest või materjalidest, võib seda pidada Ühendkuningriigi päritoluga kaubaks seal toimunud majanduslikult põhjendatud olulise töötlemise tõttu, nagu allpool märgitud.",
      "The image could not be opened. Try another image or export it as PNG.": "Pilti ei saanud avada. Proovige teist pilti või eksportige see PNG-na.",
