      "This is an application snapshot, not a complete event audit. The separate Settings activity log retains recorded actions.": "See on taotluse hetkeseis, mitte täielik sündmuste audit. Eraldi seadete tegevuslogi säilitab registreeritud toimingud.",
      "This is not a text CSV. Copy the cells from Excel or save the sheet as CSV (UTF-8).": "See pole tekstiline CSV. Kopeerige lahtrid Excelist või salvestage leht CSV-na (UTF-8).",
      "This page could not be opened. Choose another page.": "Lehte ei saanud avada. Valige teine leht.",
      "This preview stores attached filenames only. It cannot inspect or validate the contents of an uploaded document.": "Eelvaade salvestab ainult lisatud failide nimed. Üleslaaditud dokumendi sisu ei saa kontrollida ega kinnitada.",
      "This preview uses sample data saved in your browser. Approvals, payments, invitations and messages are simulated.": "Eelvaade kasutab brauserisse salvestatud näidisandmeid. Heakskiidud, maksed, kutsed ja sõnumid on näitlikud.",
      "This print has already been used. Ask the chamber to reset it.": "Seda printimist on juba kasutatud. Paluge kojal see lähtestada.",
