      "Complete the relevant transport/packing fields and declare the actual general-list items travelling. Sign the correct voucher declaration.": "Täitke asjakohased transpordi- ja pakendiväljad ning deklareerige tegelikult kaasas olevad kaubanimekirja esemed. Allkirjastage õige lehe deklaratsioon.",
