      "list package types/counts, shipping marks and identifiable goods. number separate items; avoid vague or brand-only descriptions.": "Loetlege pakendite liigid ja arvud, veomärgised ning tuvastatav kaup. Nummerdage eraldi esemed; vältige ebamääraseid või ainult kaubamärki sisaldavaid kirjeldusi.",
