      "Terms": "الشروط",
      "Text formatting": "تنسيق النص",
      "Text is never shortened automatically. Additional text below uses space in the same box; it does not create a continuation sheet.": "لا يُختصر النص تلقائيًا. يشغل النص الإضافي مساحة في الخانة نفسها ولا ينشئ ورقة متابعة.",
      "The account will leave the active list. Its applications remain available. You can restore archived accounts from Settings.": "سيغادر الحساب القائمة النشطة، وتبقى طلباته متاحة. يمكنك استعادة الحسابات المؤرشفة من الإعدادات.",
      "The application will be closed. The exporter can start a separate new application.": "سيُغلق الطلب. يمكن للمصدّر بدء طلب جديد منفصل.",
      "The chamber content will be hidden from exporters linked to ": "سيُخفى محتوى الغرفة عن المصدّرين المرتبطين بـ ",
      "The downloaded file is a design sample and has no legal effect.": "الملف المنزّل نموذج تصميم وليست له آثار قانونية.",
      "The exporter workspace contains its own sample accounts and applications. This opens the existing exporter design; it does not sign in as this company.": "تتضمن مساحة المصدّر حساباتها وطلباتها التجريبية الخاصة. يفتح هذا تصميم المصدّر الحالي ولا يسجل الدخول باسم هذه الشركة.",
      "The issue date is added when the application is submitted in the demo.": "يُضاف تاريخ الإصدار عند تقديم الطلب في العرض التجريبي.",
      "The new account starts as Pending. No invitation email is sent from this preview.": "يبدأ الحساب الجديد بحالة قيد الانتظار. لا تُرسل دعوة بريدية من هذه المعاينة.",
      "The original status reporting API is represented by local report downloads in this preview.": "تمثل تنزيلات التقارير المحلية في المعاينة واجهة تقارير الحالة الأصلية.",
      "The sample carnet is ready to return": "الدفتر التجريبي جاهز للإرجاع",
      "Theme": "السمة",
      "These are managed by the service provider.": "يديرها مزوّد الخدمة.",
      "These checks do not prevent you from continuing. Compare them with the application details.": "لا تمنعك هذه الفحوص من المتابعة. قارنها ببيانات الطلب.",
      "These details are copied into new drafts. Existing applications keep their current values.": "تُنسخ هذه البيانات إلى المسودات الجديدة. تحتفظ الطلبات الحالية بقيمها.",
      "These preferences apply to this account or Chamber User in this browser. No email, sound or push notification is sent.": "تسري هذه التفضيلات على هذا الحساب أو مستخدم الغرفة في هذا المتصفح. لا تُرسل رسائل بريدية أو أصوات أو إشعارات دفع.",
      "These values demonstrate the access screen and cannot open a real carnet.": "هذه القيم لتوضيح شاشة الوصول ولا تفتح دفترًا فعليًا.",
