      "Handling time runs from submission to the final decision, including nights, weekends and time waiting. It is attributed to the final decision-maker; it does not measure active working time. Averages count each application once and exclude missing or invalid timestamps. Document totals count each selected type once per application, including archived records, not originals or copies. Times are shown in UK time.": "يمتد وقت المعالجة من التقديم إلى القرار النهائي، بما يشمل الليالي وعطلات نهاية الأسبوع والانتظار. يُنسب إلى متخذ القرار النهائي ولا يقيس وقت العمل الفعلي. تحتسب المتوسطات كل طلب مرة وتستبعد التوقيتات المفقودة أو غير الصالحة. تحتسب إجماليات المستندات كل نوع مختار مرة لكل طلب، بما فيه المؤرشف، وليس الأصول أو النسخ. تُعرض الأوقات بتوقيت المملكة المتحدة.",
