      "How your chamber will receive the commercial invoice and any other documents.": "كيف تستلم غرفتك الفاتورة التجارية وأي مستندات أخرى.",
      "IIC issuing arrangements are limited and requirements depend on the requesting overseas authority. Confirm acceptance and the issuing route before completing the form.": "ترتيبات إصدار IIC محدودة وتعتمد المتطلبات على الجهة الأجنبية الطالبة. تأكد من القبول ومسار الإصدار قبل تعبئة النموذج.",
      "ISSUED RETROSPECTIVELY": "صادرة بأثر رجعي",
      "Identify both parties to the preferential trade arrangement, using the applicable country or territory wording.": "حدّد طرفي الترتيب التجاري التفضيلي باستخدام تسميات البلد أو الإقليم المعمول بها.",
      "Identify each article with make, model and serial number where relevant. State NSN where appropriate; packaging alone is insufficient.": "عرّف كل صنف بالعلامة والطراز والرقم التسلسلي عند اللزوم. اذكر NSN حيث ينطبق؛ التعبئة وحدها لا تكفي.",
      "Identify each product and its correct commodity code. Include the origin information required by the market.": "حدّد كل منتج ورمز سلعته الصحيح. أدرج بيانات المنشأ المطلوبة للسوق.",
      "Identify the destination partner. Check the applicable agreement and any special territorial wording.": "حدّد شريك الوجهة. راجع الاتفاقية المطبقة وأي صياغة إقليمية خاصة.",
      "Identify the method of transport.": "حدّد وسيلة النقل.",
      "Identify the originating organisation and final destination; add UK representative details where required.": "حدّد الجهة الأصلية والوجهة النهائية؛ وأضف بيانات الممثل البريطاني حيث يلزم.",
      "Identify the overseas recipient and full address. Confirm appropriate wording when the buyer is unknown.": "حدّد المستلم الخارجي وعنوانه الكامل. تأكد من الصياغة المناسبة عند عدم معرفة المشتري.",
      "Identify the responsible company or individual; the holder bears liability if the Carnet is misused.": "حدّد الشركة أو الشخص المسؤول؛ يتحمل الحامل المسؤولية عند إساءة استخدام الدفتر.",
      "If different from the importer, give the intended user’s name and address.": "إذا اختلف المستخدم عن المستورد، فاذكر اسمه وعنوانه.",
      "Illustration only: item 1 · EXP-001–012 · 12 cartons · stainless-steel fasteners.": "للتوضيح فقط: البند 1 · EXP-001–012 · 12 صندوقًا · مثبتات من الفولاذ المقاوم للصدأ.",
