      "Select ": "تحديد ",
      "Select New application, choose documents and a destination, then work through Carnet details for ATA Carnets or Shipment details for other documents. Use sample details to explore the complete flow.": "اختر طلبًا جديدًا، وحدّد المستندات والوجهة، ثم أكمل تفاصيل الدفتر لدفاتر ATA أو تفاصيل الشحنة للمستندات الأخرى. استخدم البيانات التجريبية لاستكشاف المسار كاملًا.",
      "Select a category to filter · ": "اختر فئة للتصفية · ",
      "Select a chamber before saving.": "حدّد غرفة قبل الحفظ.",
