      "Show quantities matching the supporting order, invoice or contract.": "أظهر كميات تطابق أمر الشراء أو الفاتورة أو العقد الداعم.",
      "Show the goods total and relevant additional charges, such as freight or insurance.": "أظهر إجمالي البضائع والرسوم الإضافية ذات الصلة، مثل الشحن أو التأمين.",
      "Signature preview": "معاينة التوقيع",
