      "Use new UK Certificate of Origin form": "استخدام نموذج شهادة المنشأ البريطانية الجديد",
      "Use retail value for new goods and replacement value for used goods. State the currency.": "استخدم قيمة التجزئة للبضائع الجديدة وقيمة الاستبدال للمستعملة. اذكر العملة.",
      "Use specific countries. For multiple origins, connect each origin to its goods in Box 6.": "استخدم بلدانًا محدّدة. عند تعدد المناشئ، اربط كل منشأ ببضائعه في الخانة 6.",
      "Use stored details or enter them below.": "استخدم التفاصيل المحفوظة أو أدخلها أدناه.",
      "Use template ": "استخدام القالب ",
      "Use the Formal undertaking page to view renewal information and download a sample. Ask your chamber about the legal requirements for a real account.": "استخدم صفحة التعهد الرسمي لعرض معلومات التجديد وتنزيل عينة. اسأل غرفتك عن المتطلبات القانونية للحساب الحقيقي.",
      "Use the ISO origin-country code when origin differs from the Carnet’s issuing territory.": "استخدم رمز ISO لبلد المنشأ عندما يختلف عن إقليم إصدار الدفتر.",
      "Use the applicable duplicate, retrospective or replacement endorsement; otherwise leave blank.": "استخدم العبارة المناسبة للنسخة المكررة أو الإصدار بأثر رجعي أو الاستبدال؛ وإلا فاترك الحقل فارغًا.",
      "Use the importer’s reference if required; this field may be optional on the issuer’s form.": "استخدم مرجع المستورد عند الحاجة؛ قد يكون هذا الحقل اختياريًا في نموذج الجهة المصدرة.",
      "Use the named fields on the issuing chamber’s International Import Certificate form.": "استخدم الحقول المسمّاة في نموذج شهادة الاستيراد الدولية للغرفة المصدرة.",
