      "Application details, supporting evidence and origin / eligibility must all be checked before approval.": "يجب التحقّق من تفاصيل الطلب والأدلة الداعمة والمنشأ / الأهلية قبل الاعتماد.",
      "List package types/counts, shipping marks and identifiable goods. Number separate items; avoid vague or brand-only descriptions.": "اذكر أنواع الطرود وأعدادها وعلامات الشحن والبضائع القابلة للتعريف. رقّم الأصناف المنفصلة؛ وتجنّب الأوصاف الغامضة أو أسماء العلامات التجارية وحدها.",
      "Include matching shipping marks, invoice-consistent descriptions, package details, weights and manufacturers’ names/addresses. Confirm any exception with the chamber.": "أدرج علامات الشحن المطابقة والأوصاف المتوافقة مع الفاتورة وتفاصيل الطرود والأوزان وأسماء جهات التصنيع وعناوينها. أكّد أي استثناء مع الغرفة.",
      "Confirm destination-specific signature, original/copy and legalisation requirements with the issuing chamber.": "أكّد متطلبات التوقيع والأصل/النسخة والتصديق القانوني الخاصة بالوجهة مع الغرفة المصدرة.",
      "Paper Carnet cover, general list and movement pages. Check current paper/digital arrangements for your route.": "غلاف الدفتر الورقي والقائمة العامة وصفحات الحركة. تحقّق من الترتيبات الورقية/الرقمية الحالية لمسارك.",
      "Complete the relevant transport/packing fields and declare the actual general-list items travelling. Sign the correct voucher declaration.": "أكمل حقول النقل/التعبئة المعنية وصرّح بأصناف القائمة العامة التي تسافر فعلًا. وقّع إقرار القسيمة الصحيح.",
      "Confirm the document type, destination and certification/legalisation route with your chamber before preparing an upload.": "أكّد نوع المستند والوجهة ومسار التصديق/التصديق القانوني مع غرفتك قبل إعداد الملف للرفع.",
      "Open My account → Switch / add account. Each account has its own applications, saved records, settings and team.": "افتح حسابي ← تبديل / إضافة حساب. لكل حساب طلباته وسجلاته المحفوظة وإعداداته وفريقه.",
      "Use Preview documents in the application editor or application details. Select a document, then choose Print / save PDF. Every preview is marked SAMPLE.": "استخدم معاينة المستندات في محرر الطلب أو تفاصيله. اختر مستندًا ثم طباعة / حفظ PDF. تحمل كل معاينة علامة SAMPLE.",
      "Select a category to filter": "اختر فئة للتصفية",
