      "quantity checks compare only matching, explicit package units; review any differences against the shipment.": "تُقارَن الكميات فقط عند تطابق وحدات التعبئة المحددة؛ راجع أي فروق مع بيانات الشحنة.",
      "a general description is only suitable when the supporting invoice gives full identifying details. Itemise different goods where required and show the invoice number and date in Box 10.": "يصلح الوصف العام فقط إذا كانت الفاتورة الداعمة تتضمن تفاصيل التعريف الكاملة. افصل السلع المختلفة عند الحاجة، واذكر رقم الفاتورة وتاريخها في الخانة 10.",
