      "iic issuing arrangements are limited and requirements depend on the requesting overseas authority. confirm acceptance and the issuing route before completing the form.": "ترتيبات إصدار IIC محدودة وتعتمد المتطلبات على الجهة الأجنبية الطالبة. تأكد من القبول ومسار الإصدار قبل تعبئة النموذج.",
      "issued retrospectively": "صادرة بأثر رجعي",
