      "identify each article with make, model and serial number where relevant. state nsn where appropriate; packaging alone is insufficient.": "عرّف كل صنف بالعلامة والطراز والرقم التسلسلي عند اللزوم. اذكر NSN حيث ينطبق؛ التعبئة وحدها لا تكفي.",
