      "the uk form is preprinted uk. confirm that the goods qualify.": "يُطبع UK مسبقًا على النموذج البريطاني. تأكّد من أهلية البضائع.",
      "the archive change could not be saved. browser storage is unavailable or full. please try again.": "تعذّر حفظ تغيير الأرشيف. مساحة تخزين المتصفح غير متاحة أو ممتلئة. حاول مجددًا.",
      "the authorised declarant signs and dates the accurate declaration; follow the issuer’s signature requirements.": "يوقّع المصرّح المفوّض الإقرار الدقيق ويؤرّخه؛ اتبع متطلبات توقيع الجهة المصدرة.",
      "the autosave could not be read. your existing copy has been kept.": "تعذّرت قراءة الحفظ التلقائي. تم الاحتفاظ بنسختك الحالية.",
      "the chamber prints the approved documents and returns them by your selected method.": "تطبع الغرفة المستندات المعتمدة وتعيدها بالطريقة التي اخترتها.",
      "the chamber rejected this application.": "رفضت الغرفة هذا الطلب.",
      "the checklist is hidden and does not block approval. previously saved checks are retained.": "قائمة المراجعة مخفية ولا تمنع الاعتماد. يتم الاحتفاظ بالفحوص المحفوظة سابقًا.",
      "the consignee address is incomplete.": "عنوان المرسَل إليه غير مكتمل.",
      "the end date must be on or after the start date.": "يجب أن يكون تاريخ الانتهاء في تاريخ البدء أو بعده.",
      "the exporter prints the approved documents in their workplace.": "يطبع المصدّر المستندات المعتمدة في مكان عمله.",
      "the file could not be opened. try another image or pdf.": "تعذّر فتح الملف. جرّب صورة أو ملف PDF آخر.",
      "the file could not be read. try copying the cells into the box instead.": "تعذّرت قراءة الملف. جرّب نسخ الخلايا إلى المربع بدلًا من ذلك.",
      "the goods are of foreign origin as proved by the documents attached to this application as per standard rules (e.g. foreign certificate of origin, certified invoice, customs declaration or other documents).": "البضائع ذات منشأ أجنبي كما تثبته المستندات المرفقة بهذا الطلب وفق القواعد القياسية (مثل شهادة منشأ أجنبية أو فاتورة مصدّقة أو إقرار جمركي أو غيرها).",
      "the goods whilst not comprised wholly of united kingdom components or materials, are entitled to be considered as of united kingdom origin by virtue of the economically justified substantial process which has occurred in the united kingdom, as indicated below.": "رغم أن البضائع ليست مكوّنة بالكامل من أجزاء أو مواد بريطانية، فإنها تستحق اعتبارها ذات منشأ بريطاني بسبب المعالجة الجوهرية المبرّرة اقتصاديًا التي جرت في المملكة المتحدة، كما هو موضّح أدناه.",
      "the image could not be opened. try another image or export it as png.": "تعذّر فتح الصورة. جرّب صورة أخرى أو صدّرها بتنسيق PNG.",
      "the minimum must be no greater than the maximum.": "يجب ألا يزيد الحد الأدنى على الحد الأقصى.",
      "the original file won’t be saved.": "لن يُحفظ الملف الأصلي.",
      "the place shown in box 12.": "المكان المذكور في الخانة 12.",
      "the place shown in box 8.": "المكان المذكور في الخانة 8.",
      "the preview has an optional transport field. its availability does not override this official completion instruction.": "تتضمن المعاينة حقل نقل اختياريًا. توفره لا يلغي تعليمات التعبئة الرسمية هذه.",
      "the recovery copy changed. reopen the application before discarding it.": "تغيّرت نسخة الاسترداد. أعد فتح الطلب قبل تجاهلها.",
      "the required checks and processing details are complete. review the documents, then approve when you are satisfied.": "الفحوص المطلوبة وتفاصيل المعالجة مكتملة. راجع المستندات، ثم اعتمدها عندما تكون راضيًا عنها.",
      "the resolution is retained with the claim. you can reopen a claim later.": "تُحفظ التسوية مع المطالبة. يمكنك إعادة فتحها لاحقًا.",
      "the review could not be saved. browser storage may be unavailable or full.": "تعذّر حفظ المراجعة. قد تكون مساحة تخزين المتصفح غير متاحة أو ممتلئة.",
      "the row to copy no longer exists.": "الصف المراد نسخه لم يعد موجودًا.",
