      "the saved dashboard could not be loaded.": "تعذّر تحميل لوحة المعلومات المحفوظة.",
      "the setting could not be saved. browser storage may be unavailable or full. try again.": "تعذّر حفظ الإعداد. قد تكون مساحة تخزين المتصفح غير متاحة أو ممتلئة. حاول مجددًا.",
      "the start date must be on or before the end date.": "يجب أن يكون تاريخ البدء في تاريخ الانتهاء أو قبله.",
      "the supporting evidence does not substantiate the stated origin.": "الأدلة الداعمة لا تثبت المنشأ المذكور.",
      "theatrical effects": "مؤثرات مسرحية",
      "these changes could not be kept for later. save your draft before leaving this page.": "تعذّر الاحتفاظ بهذه التغييرات. احفظ مسودتك قبل مغادرة الصفحة.",
      "this pdf could not be opened. try another pdf or an image.": "تعذّر فتح ملف PDF هذا. جرّب ملف PDF آخر أو صورة.",
      "this pdf is password protected. upload an unlocked copy or an image of the signature.": "ملف PDF محمي بكلمة مرور. ارفع نسخة غير مقفلة أو صورة للتوقيع.",
      "this action is only available for approved applications.": "هذا الإجراء متاح للطلبات المعتمدة فقط.",
      "this application is already archived.": "هذا الطلب مؤرشف بالفعل.",
      "this application is now closed or submitted. its autosave cannot be restored.": "هذا الطلب مغلق أو مقدّم الآن. لا يمكن استعادة حفظه التلقائي.",
      "this change could not be saved. browser storage may be unavailable or full.": "تعذّر حفظ هذا التغيير. قد تكون مساحة تخزين المتصفح غير متاحة أو ممتلئة.",
      "this crop is too detailed. select a smaller area around the signature.": "هذا القص مفصّل أكثر من اللازم. حدّد مساحة أصغر حول التوقيع.",
      "this dashboard changed in another tab. reload the saved draft before continuing.": "تغيّرت لوحة المعلومات في علامة تبويب أخرى. أعد تحميل المسودة المحفوظة قبل المتابعة.",
      "this dashboard changed in another tab. reload the saved draft to continue.": "تغيّرت لوحة المعلومات في علامة تبويب أخرى. أعد تحميل المسودة المحفوظة للمتابعة.",
      "this dashboard could not be loaded. your saved content has not been changed.": "تعذّر تحميل لوحة المعلومات. لم يتغيّر محتواك المحفوظ.",
      "this dashboard is too large. use smaller images or fewer blocks.": "لوحة المعلومات كبيرة جدًا. استخدم صورًا أصغر أو كتلًا أقل.",
      "this email is already on the account.": "عنوان البريد الإلكتروني هذا موجود في الحساب بالفعل.",
      "this guide covers completion. selecting invoice certification in trade documents does not itself certify an invoice.": "يغطي هذا الدليل التعبئة. اختيار تصديق الفاتورة في Trade Documents لا يصدّق الفاتورة بحد ذاته.",
      "this image could not be opened. please choose another image.": "تعذّر فتح هذه الصورة. اختر صورة أخرى.",
      "this image is too large to edit. resize it to under 40 megapixels first.": "هذه الصورة كبيرة جدًا للتحرير. صغّرها إلى أقل من 40 ميغابكسل أولًا.",
      "this is a design prototype. it does not issue valid certificates, send applications to a chamber, accept payments or grant real account access.": "هذا نموذج أولي للتصميم. لا يُصدر شهادات صالحة ولا يرسل طلبات إلى الغرفة ولا يقبل مدفوعات ولا يمنح وصولًا حقيقيًا للحساب.",
      "this is an application snapshot, not a complete event audit. the separate settings activity log retains recorded actions.": "هذه لقطة للطلب وليست سجل تدقيق كاملًا للأحداث. يحتفظ سجل نشاط الإعدادات المنفصل بالإجراءات المسجّلة.",
      "this is not a text csv. copy the cells from excel or save the sheet as csv (utf-8).": "هذا ليس ملف CSV نصيًا. انسخ الخلايا من Excel أو احفظ الورقة بصيغة CSV ‏(UTF-8).",
      "this page could not be opened. choose another page.": "تعذّر فتح هذه الصفحة. اختر صفحة أخرى.",
      "this preview stores attached filenames only. it cannot inspect or validate the contents of an uploaded document.": "تحفظ هذه المعاينة أسماء الملفات المرفقة فقط. ولا يمكنها فحص محتوى المستند المرفوع أو التحقق منه.",
      "this preview uses sample data saved in your browser. approvals, payments, invitations and messages are simulated.": "تستخدم هذه المعاينة بيانات تجريبية محفوظة في متصفحك. الاعتمادات والمدفوعات والدعوات والرسائل محاكاة.",
      "this print has already been used. ask the chamber to reset it.": "استُخدمت هذه الطباعة بالفعل. اطلب من الغرفة إعادة ضبطها.",
      "this printing action is not available for this application.": "إجراء الطباعة هذا غير متاح لهذا الطلب.",
      "this record is no longer available.": "هذا السجل لم يعد متاحًا.",
      "this reference is already in use.": "هذا المرجع مستخدم بالفعل.",
      "this report includes all matching approved ata carnets. it does not verify aviva cover, policy eligibility or insurer submission requirements.": "يتضمن هذا التقرير جميع دفاتر ATA المعتمدة المطابقة. ولا يتحقّق من تغطية Aviva أو أهلية الوثيقة أو متطلبات التقديم لشركة التأمين.",
      "this review is locked by another chamber user. its autosave has been kept.": "هذه المراجعة مقفلة بواسطة مستخدم آخر في الغرفة. تم الاحتفاظ بحفظها التلقائي.",
      "this selection is small and may look soft. a clearer source image will give a better result.": "هذا التحديد صغير وقد يبدو غير واضح. ستعطي صورة مصدر أوضح نتيجة أفضل.",
