      "use holder name and holder address in trade documents.": "استخدم حقلي اسم الحامل وعنوانه في Trade Documents.",
      "use origin & evidence in trade documents. a completed sample does not establish preferential origin.": "استخدم المنشأ والإثباتات في Trade Documents. العينة المكتملة لا تثبت المنشأ التفضيلي.",
      "use trade documents’s cumulation choice and country field. ask the chamber to confirm the required endorsement before issue.": "استخدم خيار التراكم وحقل البلد في Trade Documents. اطلب من الغرفة تأكيد العبارة المطلوبة قبل الإصدار.",
      "use a file or pasted selection smaller than 1 mb.": "استخدم ملفًا أو تحديدًا ملصقًا أصغر من 1 ميغابايت.",
      "use a permitted signatory; obtain employee authorisation where the chamber requires it.": "استخدم موقّعًا معتمدًا؛ واحصل على تفويض الموظف إذا طلبته الغرفة.",
      "use a unique invoice reference and the issue date.": "استخدم مرجع فاتورة فريدًا وتاريخ الإصدار.",
